{
  "up": "Select distinct canonical_smiles, molecule_chembl_id, standard_type, standard_relation, standard_value, standard_units from molecule_dictionary m join activities a on m.molregno = a.molregno join assays ass on a.assay_id = ass.assay_id join compound_structures cs on m.molregno = cs.molregno where ass.chembl_id = 'CHEMBL1614079' and a.standard_value is not null and a.standard_relation = '=' order by canonical_smiles, molecule_chembl_id, standard_type, standard_relation, standard_value, standard_units"
}
